fn gcd(a: i32, b: i32) -> i32 {
    let mut x: i32 = a;
    let mut y: i32 = b;
    while y != 0 {
        let r: i32 = x % y;
        x = y;
        y = r;
    }
    x
}

fn frame(t: i32) {
    let g: i32 = gcd(252, 105);
    let l: i32 = 252 / g * 105;
    host::display::clear(0x000000);
    host::display::draw_string(8, 10, "GCD 252 105", 0x808080, 1);
    host::display::draw_number(8, 26, g, 0xffffff, 2);
    host::display::draw_string(8, 60, "LCM", 0x808080, 1);
    host::display::draw_number(8, 76, l, 0x00ffff, 2);
    host::display::present();
}
